function slowestPace(pages: number[], hours: number): number {
  const fits = (speed: number): boolean => {
    let total = 0;
    for (const p of pages) {
      total += Math.ceil(p / speed);
      if (total > hours) return false;
    }
    return true;
  };
  let lo = 1, hi = Math.max(...pages); // answer in [lo, hi]; hi always fits
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2); // avoids 32-bit >>, which breaks once lo + hi passes 2^31
    if (fits(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

